ln, err := net.Listen("tcp", ":8080")
if err != nil { log.Fatal(err) }
sem := make(chan struct{}, 1024)                 // bound the connections, not the threads
for {
    c, err := ln.Accept()                        // the goroutine parks in the netpoller
    if err != nil { continue }
    sem <- struct{}{}
    go func(c net.Conn) {
        defer func() { <-sem; c.Close() }()
        io.Copy(c, c)                            // blocking style; readiness is the runtime's job
    }(c)
}
